#if canImport(UIKit)
import SwiftUI
import FloeElectronicsCore
import FloeElectronicsUI
import FloeWorkspace

/// Prepares the generated bytes for the existing read-only engineering reader.
/// No URL, store, parser or renderer is introduced by this adapter.
enum ElectronicsExportPreviewPreparation {
    enum Failure: Error { case unsupportedFile, emptyOutput, tooLarge, provenanceMismatch }
    nonisolated static func package(file: EDAExchangeFile) throws -> EngineeringPreviewPackage {
        try Task.checkCancellation()
        guard file.name == (file.name as NSString).lastPathComponent,
              !file.name.contains("\\"), EngineeringPreviewKind.identify(file.name) == .gerber else { throw Failure.unsupportedFile }
        guard !file.data.isEmpty else { throw Failure.emptyOutput }
        guard file.data.count <= EngineeringPreviewPackage.maximumBytes else { throw Failure.tooLarge }
        let package = try EngineeringPreviewPackage.single(name: file.name, bytes: file.data)
        guard package.kind == .gerber, package.files.count == 1,
              package.provenance.sourceName == file.name,
              package.provenance.sourceByteCount == file.data.count,
              package.provenance.sourceSHA256 == file.sha256 else { throw Failure.provenanceMismatch }
        try Task.checkCancellation()
        return package
    }
}

private struct ElectronicsExportPreviewRoute: Identifiable {
    enum Phase { case loading, ready(EngineeringPreviewPackage), failed(String) }
    let id: UUID
    let name: String
    var phase: Phase
}

/// The existing electronics session remains the only editing/saving owner.
/// The outer personal editor continues to own its assistant and close flow.
@MainActor struct ElectronicsEditorSurface: View {
    let session: ElectronicsProjectSession
    @State private var active = false
    @State private var generation: UUID?
    @State private var preview: ElectronicsExportPreviewRoute?
    @State private var preparation: Task<Void, Never>?

    var body: some View {
        EDWorkbenchView(session: session.workbench, onExportPreview: { file, revision in
            requestPreview(file, revision: revision)
        })
        .onAppear { active = true }
        .onDisappear { active = false; cancelPreview() }
        .onChange(of: ObjectIdentifier(session)) { _, _ in cancelPreview() }
        .onChange(of: session.workbench.revision) { _, _ in cancelPreview() }
        .onChange(of: session.workbench.isClosed) { _, closed in if closed { cancelPreview() } }
        .sheet(item: $preview) { route in
            ElectronicsExportPreviewSheet(route: route)
                .id(route.id)
                .onDisappear { cancelPreview(ifGeneration: route.id) }
        }
    }

    private func matches(_ source: ElectronicsProjectSession, projectID: UUID, revision: UInt64) -> Bool {
        guard active, session === source, source.id == projectID,
              source.workbench.project.id == projectID,
              !source.workbench.isClosed, !source.workbench.busy,
              !source.workbench.isDirty, !source.workbench.conflictWithOriginal,
              source.workbench.revision == revision else { return false }
        return (try? ElectronicsProjectSession.existing(id: projectID, directory: source.directory)) === source
    }

    private func requestPreview(_ file: EDAExchangeFile, revision: UInt64) {
        let source = session, projectID = session.id
        guard matches(source, projectID: projectID, revision: revision),
              EngineeringPreviewKind.identify(file.name) == .gerber else { cancelPreview(); return }
        let previous = preparation
        previous?.cancel()
        let token = UUID()
        generation = token
        preview = .init(id: token, name: file.name, phase: .loading)
        guard file.data.count <= EngineeringPreviewPackage.maximumBytes else {
            preview = .init(id: token, name: file.name, phase: .failed(IDELanguageRunText.t(
                "此文件超过预览大小限制，仍可存储或分享。", "This file exceeds the preview limit. You can still save or share it.")))
            return
        }
        preparation = Task { @MainActor in
            // A replacement waits for cancellation to join the previous worker.
            await previous?.value
            guard !Task.isCancelled, generation == token else { return }
            guard matches(source, projectID: projectID, revision: revision) else { cancelPreview(ifGeneration: token); return }
            let worker = Task.detached(priority: .userInitiated) {
                try ElectronicsExportPreviewPreparation.package(file: file)
            }
            defer { if generation == token { preparation = nil } }
            do {
                let package = try await withTaskCancellationHandler(operation: {
                    try await worker.value
                }, onCancel: { worker.cancel() })
                try Task.checkCancellation()
                guard generation == token else { return }
                guard matches(source, projectID: projectID, revision: revision) else { cancelPreview(ifGeneration: token); return }
                preview = .init(id: token, name: file.name, phase: .ready(package))
            } catch {
                guard !Task.isCancelled, generation == token else { return }
                guard matches(source, projectID: projectID, revision: revision) else { cancelPreview(ifGeneration: token); return }
                preview = .init(id: token, name: file.name, phase: .failed(IDELanguageRunText.t(
                    "无法预览此文件，请重新生成后重试。", "Couldn’t preview this file. Generate it again and retry.")))
            }
        }
    }

    private func cancelPreview(ifGeneration expected: UUID? = nil) {
        if let expected, generation != expected { return }
        generation = nil
        preparation?.cancel()
        // Keep the cancelled handle until it has joined, so a new request can
        // await it. A stale completion never writes into a newer presentation.
        preview = nil
    }
}

@MainActor private struct ElectronicsExportPreviewSheet: View {
    let route: ElectronicsExportPreviewRoute
    @Environment(\.dismiss) private var dismiss
    var body: some View {
        NavigationStack {
            Group {
                switch route.phase {
                case .loading:
                    ProgressView(IDELanguageRunText.t("正在准备预览…", "Preparing preview…"))
                case .ready(let package):
                    EngineeringFilePreview(package: package)
                case .failed(let message):
                    ContentUnavailableView {
                        Label(IDELanguageRunText.t("无法预览", "Can’t preview"), systemImage: "doc.viewfinder")
                    } description: { Text(message) }
                }
            }
            .navigationTitle(route.name)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button(IDELanguageRunText.t("完成", "Done")) { dismiss() }
                }
            }
        }
        .accessibilityIdentifier("electronics.output.previewSheet")
    }
}
#endif
